export const EXAMPLES = "# Example parts\n\nReal scripts from Parasocial's example documents.\n\n## examples/bracket/parts/bracket.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\n\nexport default part(\"Bracket\", ({ color }) => {\n  const t = param(\"thickness\", 3, { min: 1, max: 10, unit: mm, step: 0.5 });\n  const w = param(\"width\", 40, { unit: mm });\n\n  const base = sketch(plane.XY)\n    .rect(w, 25, { center: true, tag: \"outline\" })\n    .circle([0, 0], 4, { tag: \"bore\" })\n    .extrude(t, { tag: \"base\" });\n\n  return base\n    .fillet(base.edges(\"base.side\").parallelTo(\"Z\"), 2, { tag: \"corners\" })\n    .chamfer(base.edges(\"base.cap.end & bore\"), 0.5)\n    .color(color.auto());\n});\n```\n\n## examples/enclosure/parts/body.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\n\nexport default part(\"Body\", ({ color }) => {\n  const w = param(\"width\", 80, { min: 30, max: 200, unit: mm });\n  const d = param(\"depth\", 50, { min: 30, max: 200, unit: mm });\n  const h = param(\"height\", 30, { min: 10, max: 120, unit: mm });\n  const wall = param(\"wall\", 2, { min: 1, max: 5, unit: mm, step: 0.2 });\n\n  const shell = sketch(plane.XY).rect(w, d, { tag: \"outer\" }).extrude(h, { tag: \"block\" });\n  const rounded = shell.fillet(shell.edges(\"block.side\").parallelTo(\"Z\"), 6, { tag: \"corners\" });\n  const cavity = sketch(plane.XY.offset(wall))\n    .rect(w - 2 * wall, d - 2 * wall, { tag: \"inner\" })\n    .extrude(h, { tag: \"cavity\" });\n  const hollow = rounded.subtract(cavity, { tag: \"hollow\" });\n\n  // cable port on the front wall\n  const port = sketch(plane.XZ.offset(d / 2 + 1))\n    .slot([-8, h / 2], [8, h / 2], 6, { tag: \"port\" })\n    .extrude(wall + 2, { tag: \"portCut\" });\n  return hollow\n    .subtract(port, { tag: \"portHole\" })\n    .fillet(hollow.edges(\"cap.start & corners\"), 1.5, { tag: \"footRound\" })\n    .color(color.auto())\n    .material(\"petg\");\n});\n```\n\n## examples/enclosure/parts/lid.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\n\nexport default part(\"Lid\", ({ color }) => {\n  const w = param(\"width\", 80, { min: 30, max: 200, unit: mm });\n  const d = param(\"depth\", 50, { min: 30, max: 200, unit: mm });\n  const t = param(\"thickness\", 2.5, { min: 1, max: 6, unit: mm, step: 0.1 });\n  const lip = param(\"lip\", 3, { min: 1, max: 8, unit: mm });\n  const wall = 2, clearance = 0.2;\n\n  const plate = sketch(plane.XY).rect(w, d, { tag: \"plate\" }).extrude(t, { tag: \"top\" });\n  const lidPlate = plate.fillet(plate.edges(\"top.side\").parallelTo(\"Z\"), 6, { tag: \"corners\" });\n  const ring = sketch(plane.XY.offset(-lip))\n    .rect(w - 2 * wall - 2 * clearance, d - 2 * wall - 2 * clearance, { tag: \"lipOuter\" })\n    .rect(w - 4 * wall, d - 4 * wall, { tag: \"lipInner\" })\n    .extrude(lip, { tag: \"lip\" });\n  return lidPlate\n    .union(ring, { tag: \"joined\" })\n    .chamfer(lidPlate.edges(\"top.cap.end & corners\"), 0.6, { tag: \"topEdge\" })\n    .translate([0, 0, 40])\n    .color(color.auto())\n    .material(\"petg\");\n});\n```\n\n## examples/flange/lib/holes.ts\n\n```ts\nimport { cylinder, type Solid } from \"parasocial\";\n\n/** `count` through-holes of `diameter` on a circle of `radius`, as one tool body. */\nexport function boltCircle(count: number, radius: number, diameter: number, height: number): Solid {\n  const hole = cylinder(diameter / 2, height + 2, { at: [radius, 0, -1], tag: \"bolt\" });\n  return hole.circularPattern(count, { tag: \"bolts\" });\n}\n```\n\n## examples/flange/parts/flange.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\nimport { boltCircle } from \"../lib/holes\";\n\nexport default part(\"Flange\", ({ color }) => {\n  const od = param(\"outerDiameter\", 90, { min: 40, max: 200, unit: mm });\n  const bore = param(\"bore\", 30, { min: 5, max: 80, unit: mm });\n  const t = param(\"thickness\", 8, { min: 3, max: 30, unit: mm, step: 0.5 });\n  const hub = param(\"hubHeight\", 14, { min: 0, max: 60, unit: mm });\n  const bolts = param(\"bolts\", 6, { options: [4, 6, 8] });\n  const boltD = param(\"boltDiameter\", 5.5, { min: 2, max: 14, unit: mm, step: 0.1 });\n\n  // half cross-section in XZ, revolved around Z\n  const r = od / 2, rb = bore / 2, rh = rb + 8;\n  const body = sketch(plane.XZ, { tag: \"section\" })\n    .moveTo([rb, 0])\n    .lineTo([r, 0], { tag: \"bottom\" })\n    .lineTo([r, t], { tag: \"rim\" })\n    .lineTo([rh, t], { tag: \"shoulder\" })\n    .lineTo([rh, t + hub], { tag: \"hub\" })\n    .lineTo([rb, t + hub], { tag: \"top\" })\n    .close({ tag: \"bore\" })\n    .revolve(360, { axis: \"Z\", tag: \"body\" });\n\n  const drilled = body.subtract(boltCircle(bolts, (r + rh) / 2, boltD, t), { tag: \"drill\" });\n  return drilled\n    .fillet(drilled.edges(\"shoulder & hub\"), 3, { tag: \"hubFillet\" })\n    .chamfer(drilled.edges(\"rim & body.side.bottom\"), 1, { tag: \"edgeBreak\" })\n    .color(color.auto())\n    .material(\"steel\");\n});\n```\n\n## examples/gasket/parts/gasket.ts\n\n```ts\nimport { part, param, sketch, plane, mm } from \"parasocial\";\n\nexport default part(\"Gasket\", ({ color }) => {\n  const w = param(\"width\", 70, { unit: mm });\n  const d = param(\"depth\", 40, { unit: mm });\n  const t = param(\"thickness\", 1.5, { min: 0.5, max: 4, unit: mm, step: 0.1 });\n  const s = sketch(plane.XY, { tag: \"outline\" })\n    .rect(w, d, { tag: \"edge\" })\n    .rect(w - 12, d - 12, { tag: \"window\" });\n  for (const [x, y] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) s.circle([x * (w / 2 - 3), y * (d / 2 - 3)], 1.6);\n  s.slot([-8, d / 2 - 3], [8, d / 2 - 3], 2.4, { tag: \"keyway\" });\n  return s.extrude(t, { tag: \"sheet\" }).color(color.auto()).material(\"nylon\");\n});\n```\n\n## examples/knob/parts/knob.ts\n\n```ts\nimport { part, param, sketch, plane, cylinder, mm } from \"parasocial\";\n\nexport default part(\"Knob\", ({ color }) => {\n  const d = param(\"diameter\", 30, { min: 12, max: 80, unit: mm });\n  const h = param(\"height\", 16, { min: 6, max: 40, unit: mm });\n  const grips = param(\"grips\", 18, { min: 6, max: 40, step: 1 });\n  const shaft = param(\"shaft\", 6, { min: 3, max: 10, unit: mm, step: 0.1 });\n\n  const puck = sketch(plane.XY).circle([0, 0], d / 2, { tag: \"rim\" }).extrude(h, { tag: \"body\" });\n  const body = puck.fillet(puck.edges(\"body.cap.end & rim\"), 1.5, { tag: \"topRound\" });\n  const groove = cylinder(1.2, h + 2, { at: [d / 2 + 0.4, 0, -1], tag: \"groove\" }).circularPattern(grips, { tag: \"grooves\" });\n  const knurled = body.subtract(groove, { tag: \"knurl\" });\n  const dShaft = sketch(plane.XY)\n    .moveTo([-shaft / 2, 0])\n    .threePointArc([0, -shaft / 2], [shaft / 2, 0], { tag: \"round\" })\n    .lineTo([shaft / 2, shaft * 0.3], { tag: \"flatSide\" })\n    .lineTo([-shaft / 2, shaft * 0.3], { tag: \"flat\" })\n    .close()\n    .extrude(h * 0.7, { tag: \"shaftHole\" });\n  return knurled.subtract(dShaft, { tag: \"socket\" }).color(color.auto());\n});\n```\n";
